/// Performs a binary search on a non-decreasing slice `a` for the target `k`.
/// Returns `true` if `k` is found in `a`, otherwise returns `false`.
fn bin_search(a: &[i32], k: i32) -> bool {
    let mut lo = 0;
    let mut hi = a.len();
    while lo < hi {
        // Avoid potential overflow; hi and lo are usize
        let mid = lo + (hi - lo) / 2;
        if a[mid] == k {
            return true;
        } else if a[mid] < k {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    false
}

